  msg.i_charcoal301 = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores i_charcoal301");
  msg = makeMessage();
  msg.j_mystring302 = "";
  assert.ok(!msg.equals(makeMessage()), "equals ignores j_mystring302");
  msg = makeMessage();
  msg.k_uchar303 = 0;
  assert.ok(!msg.equals(makeMessage()), "equals ignores k_uchar303");
