test("ClassyMcClassface ShortBuffer", () => {
  const msg = makeMessage();
  const wire = msg.serialize();
  const shorter = wire.slice(0, wire.length - 1);
  const target = new ClassyMcClassface();
  assert.throws(() => target.deserialize(shorter), RangeError);
  assert.ok(target.equals(new ClassyMcClassface()), "a failed deserialize changed the message");
  assert.throws(() => target.deserializeFrom(wire, 1), RangeError);
  assert.throws(() => msg.serializeInto(shorter, 0), RangeError);
  assert.throws(() => msg.serializeInto(wire, -1), RangeError);
  assert.throws(() => msg.serializeInto(wire, 0.5), RangeError);
  assert.throws(() => msg.serializeInto(wire, wire.length + 1), RangeError);
  assert.throws(() => msg.serializeInto("not a buffer", 0), TypeError);
});

test("ClassyMcClassface Offset", () => {
  const input = makeMessage();
  const wire = input.serialize();
  const backing = new Uint8Array(5 + ClassyMcClassface.SIZE + 2);
  const buf = backing.subarray(2);
  assert.equal(input.serializeInto(buf, 3), 3 + ClassyMcClassface.SIZE);
  for (let i = 0; i < backing.length; i++) {
    const want = i >= 5 && i < 5 + wire.length ? wire[i - 5] : 0;
    assert.equal(backing[i], want, `serializeInto(buf, 3) differs from serialize() at byte ${i}`);
  }
  const output = new ClassyMcClassface();
  assert.equal(output.deserializeFrom(new DataView(backing.buffer, 2), 3), 3 + ClassyMcClassface.SIZE);
  assert.ok(input.equals(output), `offset round-trip value mismatch\n in ${input}\nout ${output}`);
  const fromBuffer = new ClassyMcClassface();
  assert.equal(fromBuffer.deserializeFrom(backing.buffer, 5), 5 + ClassyMcClassface.SIZE);
  assert.ok(input.equals(fromBuffer), "deserializeFrom(ArrayBuffer) differs");
});

