test("ClassyMcClassface SetterWrap", () => {
  const msg = new ClassyMcClassface();
  msg.b_myuint32_200 = -1294967296;
  assert.equal(msg.b_myuint32_200, 3000000000, "b_myuint32_200");
  msg.c_myint64_201 = 18446744064709551616n;
  assert.equal(msg.c_myint64_201, -9000000000n, "c_myint64_201");
  msg.c_myint64_201 = 7;
  assert.equal(msg.c_myint64_201, 7n, "c_myint64_201 from a Number");
  msg.d_myfloat202 = 0.1;
  assert.equal(msg.d_myfloat202, Math.fround(0.1), "d_myfloat202");
  msg.e_myint16_203 = 53191;
  assert.equal(msg.e_myint16_203, -12345, "e_myint16_203");
  msg.f_myuint16_204 = 125536;
  assert.equal(msg.f_myuint16_204, 60000, "f_myuint16_204");
  msg.g_myint32_205 = 2294967296;
  assert.equal(msg.g_myint32_205, -2000000000, "g_myint32_205");
  msg.h_myuint64_206 = -18446744061709551616n;
  assert.equal(msg.h_myuint64_206, 12000000000n, "h_myuint64_206");
  msg.h_myuint64_206 = 7;
  assert.equal(msg.h_myuint64_206, 7n, "h_myuint64_206 from a Number");
  msg.i_charcoal301 = 206;
  assert.equal(msg.i_charcoal301, -50, "i_charcoal301");
  msg.k_uchar303 = 457;
  assert.equal(msg.k_uchar303, 201, "k_uchar303");
});

test("ClassyMcClassface Strings", () => {
  const msg = new ClassyMcClassface();
  msg.j_mystring302 = "A";
  assert.equal(msg.j_mystring302.length, 16);
  assert.equal(msg.j_mystring302[0], 65);
  assert.equal(msg.j_mystring302Text, "A");
  msg.j_mystring302 = "x".repeat(16 + 3);
  assert.equal(msg.j_mystring302Text, "x".repeat(16));
  msg.j_mystring302 = [1, 2];
  const want = new Uint8Array(16);
  want.set([1, 2].slice(0, 16));
  assert.equal(hex(msg.j_mystring302), hex(want));
  msg.j_mystring302[0] = 9;
  assert.equal(msg.j_mystring302[0], 1, "the getter returns a copy");
  assert.throws(() => { msg.j_mystring302 = 5; }, TypeError);
});

function fromHex(text) {
  return Uint8Array.from(text.match(/[0-9a-f]{2}/g) ?? [], (h) => parseInt(h, 16));
}

test("ClassyMcClassface Json", () => {
  const input = makeMessage();
  const text = input.toJsonText();
  assert.equal(text, "{\"a_mydouble100\":3.14159,\"b_myuint32_200\":3000000000,\"c_myi"
    + "nt64_201\":\"-9000000000\",\"d_myfloat202\":3.5,\"e_myint16_203"
    + "\":-12345,\"f_myuint16_204\":60000,\"g_myint32_205\":-2000000000"
    + ",\"h_myuint64_206\":\"12000000000\",\"i_charcoal301\":65,\"j_mys"
    + "tring302\":\"skywire\",\"k_uchar303\":200,\"l_myuint8_304\":201,"
    + "\"m_myint8_305\":-50,\"n_shortstring306\":\"skyw\",\"o_myfloat10"
    + "00\":3.5,\"p_myuint32_2000\":3000000000,\"q_myint64_2010\":\"-90"
    + "00000000\",\"r_mydouble2020\":3.14159}");
  const got = ClassyMcClassface.fromJsonText(text);
  assert.ok(got.equals(input), `JSON round-trip value mismatch\n in ${input}\nout ${got}`);
  assert.equal(got.toJsonText(), text);
  assert.ok(ClassyMcClassface.fromJsonText(new TextEncoder().encode(text)).equals(input), "JSON from bytes differs");
});

