test("ClassyMcClassface Bson", () => {
  const input = makeMessage();
  const data = input.toBson();
  assert.ok(data instanceof Uint8Array, "toBson() returns a Uint8Array");
  assert.equal(hex(data), hex(fromHex("9101000001615f6d79646f75626c65313030006e861bf0f921094012625f6d79"
    + "75696e7433325f32303000005ed0b20000000012635f6d79696e7436345f3230"
    + "310000e68ee7fdffffff01645f6d79666c6f6174323032000000000000000c40"
    + "10655f6d79696e7431365f32303300c7cfffff10665f6d7975696e7431365f32"
    + "30340060ea000010675f6d79696e7433325f32303500006cca8812685f6d7975"
    + "696e7436345f32303600007841cb0200000010695f63686172636f616c333031"
    + "0041000000026a5f6d79737472696e673330320008000000736b797769726500"
    + "106b5f756368617233303300c8000000106c5f6d7975696e74385f33303400c9"
    + "000000106d5f6d79696e74385f33303500ceffffff026e5f73686f7274737472"
    + "696e673330360005000000736b797700016f5f6d79666c6f6174313030300000"
    + "00000000000c4012705f6d7975696e7433325f3230303000005ed0b200000000"
    + "12715f6d79696e7436345f323031300000e68ee7fdffffff01725f6d79646f75"
    + "626c6532303230006e861bf0f921094000")));
  const got = ClassyMcClassface.fromBson(data);
  assert.ok(got.equals(input), `BSON round-trip value mismatch\n in ${input}\nout ${got}`);
  assert.equal(hex(got.toBson()), hex(data));
  assert.ok(ClassyMcClassface.fromBson(data.buffer).equals(input), "BSON from an ArrayBuffer differs");
});

test("ClassyMcClassface BsonEmptyIsDefault", () => {
  assert.ok(ClassyMcClassface.fromBson(Uint8Array.of(5, 0, 0, 0, 0)).equals(new ClassyMcClassface()));
});

test("ClassyMcClassface BsonLargeUint64_h_myuint64_206", () => {
  const cases = [
    [2n ** 64n - 1n, "13685f6d7975696e7436345f32303600ffffffffffffffff0000000000004030"],
    [2n ** 63n - 1n, "12685f6d7975696e7436345f32303600ffffffffffffff7f"],
  ];
  for (const [value, element] of cases) {
    const msg = new ClassyMcClassface();
    msg.h_myuint64_206 = value;
    const data = msg.toBson();
    assert.ok(hex(data).includes(hex(fromHex(element))), `h_myuint64_206 = ${value} is not ${element}`);
    assert.ok(ClassyMcClassface.fromBson(data).equals(msg), `h_myuint64_206 = ${value} did not read back`);
  }
});

